const fit=()=>document.querySelectorAll(".bfig svg:not([data-fit])").forEach(sv=>{try{const bb=sv.getBBox();if(!bb.width)return;sv.dataset.fit="1";const vb=sv.viewBox.baseVal,x0=Math.min(vb.x,bb.x-3),y0=Math.min(vb.y,bb.y-3),x1=Math.max(vb.x+vb.width,bb.x+bb.width+3),y1=Math.max(vb.y+vb.height,bb.y+bb.height+3);if(x0<vb.x||y0<vb.y||x1>vb.x+vb.width||y1>vb.y+vb.height)sv.setAttribute("viewBox",[x0,y0,x1-x0,y1-y0].map(v=>+v.toFixed(1)).join(" "))}catch(e){}});
